package net.civeira.phylax.features.access.usergroupmembership.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.usergroupmembership.domain.UserGroupMembership;
import net.civeira.phylax.features.access.usergroupmembership.domain.event.UserGroupMembershipEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserGroupMembershipEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserGroupMembershipEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserGroupMembership entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
